media.css:
[data-ui-unit="media"].product-media {
  width: 100%;
  aspect-ratio: 1 / 1;
  margin: 0;
  overflow: hidden;
}

[data-ui-unit="media"].product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 44% center;
}

@media (min-width: 701px) {
  [data-ui-unit="media"].product-media {
    border-radius: 8px;
  }
}

identity.css:
[data-ui-unit="identity"].product-identity .eyebrow {
  font-size: 14px;
  font-weight: 500;
  color: #60606a;
  margin-bottom: 8px;
}

[data-ui-unit="identity"].product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: #202024;
  word-break: keep-all;
  overflow-wrap: break-word;
}

[data-ui-unit="identity"].product-identity .price-row {
  margin-top: 12px;
}

[data-ui-unit="identity"].product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: #202024;
}

[data-ui-unit="identity"].product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 24px;
}

[data-ui-unit="identity"].product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

[data-ui-unit="identity"].product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  object-fit: contain;
  color: #60606a;
}

[data-ui-unit="identity"].product-identity .meta-item span {
  font-size: 14px;
  font-weight: 500;
  color: #60606a;
  white-space: nowrap;
}

[data-ui-unit="identity"].product-identity .description {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.75;
  color: #202024;
  margin-top: 20px;
}

booking.css:
[data-ui-unit="booking"] .booking-host-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
  color: #202024;
}

[data-ui-unit="booking"] .booking-host-subtitle {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: #60606a;
  margin-top: 4px;
}

[data-ui-unit="booking"] .booking-icon-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f2f2f5;
  border-radius: 8px;
  border: none;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

[data-ui-unit="booking"] .booking-icon-btn img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  pointer-events: none;
}

[data-ui-unit="booking"] .booking-icon-btn:hover {
  background-color: #e8e8ed;
}

[data-ui-unit="booking"] .booking-icon-btn:active {
  transform: scale(0.96);
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] {
  background-color: #eef0fc;
}

[data-ui-unit="booking"] .booking-primary-btn {
  min-height: 52px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  border-radius: 6px;
  border: none;
  white-space: nowrap;
  overflow-wrap: break-word;
  word-break: keep-all;
  text-align: center;
}

[data-ui-unit="booking"] .booking-note {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: #60606a;
  margin-top: 12px;
}
